<?php
namespace App\Policies;use App\Models\PartnerLicence;use App\Models\User;
final class PartnerLicencePolicy{private function allowed(User$u):bool{return$u->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','COMPLIANCE_ADMIN'])->exists();}public function viewAny(User$u):bool{return$this->allowed($u);}public function view(User$u,PartnerLicence$l):bool{return$this->allowed($u);}public function create(User$u):bool{return$this->allowed($u);}public function update(User$u,PartnerLicence$l):bool{return$l->status==='PENDING_VERIFICATION'&&$this->allowed($u);}public function delete(User$u,PartnerLicence$l):bool{return false;}}
